   762	static void ui_demo_slider_touch_event(lv_event_t *event)
   763	{
   764	  lv_obj_t *slider = lv_event_get_user_data(event);
   765	  lv_obj_t *hit_area = lv_event_get_target_obj(event);
   766	  lv_area_t coords;
   767	  lv_point_t point;
   768	  int32_t track_h;
   769	  int32_t offset_y;
   770	  int32_t value;
   771	
   772	  if (slider == NULL || hit_area == NULL || lv_indev_active() == NULL)
   773	    {
   774	      syslog(LOG_WARNING, "ui_demo: slider touch ignored slider=%p hit=%p\n",
   775	             slider, hit_area);
   776	      return;
   777	    }
   778	
   779	  lv_obj_get_coords(hit_area, &coords);
   780	  lv_indev_get_point(lv_indev_active(), &point);
   781	  syslog(LOG_INFO,
   782	         "ui_demo: slider touch %s p=(%ld,%ld) area=(%ld,%ld,%ld,%ld)\n",
   783	         ui_demo_event_name(lv_event_get_code(event)),
   784	         (long)point.x, (long)point.y,
   785	         (long)coords.x1, (long)coords.y1,
   786	         (long)coords.x2, (long)coords.y2);
   787	
   788	  track_h = coords.y2 - coords.y1;
   789	  if (track_h <= 0)
   790	    {
   791	      return;
   792	    }
   793	
   794	  offset_y = point.y - coords.y1;
   795	  value = 100 - (offset_y * 100) / track_h;
   796	  ui_demo_set_slider_value(slider, value);
   797	}
