static int hal_pwm_ch_check(u32 ch) {
  if (ch >= AIC_PWM_CH_NUM) {
    hal_log_err("ch%d is out of range, max num:%d\n", ch, AIC_PWM_CH_NUM - 1);
    return -EINVAL;
  }
