static void pwm_reg_enable(int offset, int bit, int enable) {
  int tmp;

  tmp = pwm_readl(offset);
  tmp &= ~bit;
  if (enable)
    tmp |= bit;

  pwm_writel(tmp, offset);
}

u32 hal_pwm_int_sts(void) { return pwm_readl(PWM_INTSTS); }

