void hal_pwm_int_config(u32 ch, enum aic_pwm_irq_event irq_mode, u8 enable) {
  pwm_writel((enable << PWM_ETSEL_INTEN_SHIFT) |
                 (irq_mode << PWM_ETSEL_INTSEL_SHIFT),
