void hal_pwm_ch_init(u32 ch, enum aic_pwm_mode mode, u32 default_level,
                     struct aic_pwm_action *a0, struct aic_pwm_action *a1) {
  struct aic_pwm_arg *arg = NULL;

  if (hal_pwm_ch_check(ch) < 0) {
