    return;
  }                    
  arg = &g_pwm_args[ch];

  arg->mode = mode;
  arg->available = 1;
  arg->def_level = default_level;
  memcpy(&arg->action0, a0, sizeof(struct aic_pwm_action));
  memcpy(&arg->action1, a1, sizeof(struct aic_pwm_action));

  pwm_reg_enable(PWM_CKCTL, PWM_CKCTL_PWM_ON(ch), 1);
